-- Service Data sections: admins can rename, reorder and edit the standard sections and add their own.
-- Each field is a key in a store's Service Data (generalInfo) with the label shown on the Service Data page.
create table service_sections (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  sort_order int not null default 0,
  fields jsonb not null default '[]',
  standard boolean not null default false,
  created_at timestamptz not null default now()
);
alter table service_sections enable row level security;
insert into service_sections (title, sort_order, fields, standard) values
